s=s.replace('</style>',css+'\n</style>',1)
js='''(()=>{const widths={'4x3':1920,'16x10':2304,'16x9':2560,'21x9':3360,'32x9':5120},sizes={rematch:[281,193],matchSm1:[272,372],matchSm2:[539,374],matchSm3:[555,376],matchSm4:[552,373],rewardun:[455,328]},q=id=>document.getElementById('paper-'+id);function wipe(){q('wipe-draft').style.clipPath='inset(0 0 0 '+q('wipe-input').value+'%)';}function stage(){const m=q('menu').value,ratio=q('aspect').value,w=widths[ratio],base='results-v1/'+m+'-'+ratio;q('stage-original').src=base+'-original.png';q('stage-draft').src=base+'-draft.png';q('stage-pair').dataset.bg=q('bg').value;const pct=1920/w*100;for(const e of document.querySelectorAll('.paper-safe'))Object.assign(e.style,{width:pct+'%',left:(100-pct)/2+'%'});q('stage-caption').textContent=ratio.replace('x',':')+' · '+w+'×1440 · native panel size/placement · transparent wider margins · game validation pending';}function update(){const m=q('menu').value,alpha=q('channel').value==='alpha',ref=q('ref').value,base='results-v1/'+m,orig=base+(alpha?'-faithful-alpha.png':'-'+ref+'.png'),draft=base+'-restrained'+(alpha?'-alpha':'')+'.png';for(const id of ['original','wipe-original'])q(id).src=orig;for(const id of ['draft','wipe-draft'])q(id).src=draft;q('ref-label').textContent=alpha?'Source alpha · 4× coverage':q('ref').selectedOptions[0].textContent;q('comparison').dataset.mode=q('view').value;q('comparison').dataset.bg=q('bg').value;q('wipe-controls').hidden=q('view').value!=='wipe';q('original-link').href=orig;q('draft-link').href=draft;q('mask-link').href=base+'-safe-paper-mask.png';q('raw-image').src=base+'-raw.png';q('raw-link').href=base+'-raw.png';q('caption').textContent=q('menu').selectedOptions[0].textContent+' · '+sizes[m].join('×')+' native → '+sizes[m].map(v=>v*4).join('×')+' · source alpha and graphics protected · unapproved artwork';stage();wipe();}for(const id of ['menu','ref','channel','bg','view'])q(id).onchange=update;q('aspect').onchange=stage;q('wipe-input').oninput=wipe;q('bounds').onclick=()=>{const show=q('bounds').getAttribute('aria-pressed')!=='true';q('bounds').setAttribute('aria-pressed',String(show));for(const e of document.querySelectorAll('.paper-stage-frame'))e.classList.toggle('show',show);};update();})();'''
s+='<script>'+js+'</script>\n';(p.parent/'review.html').write_text(s);print('Sixpaperpanels first;native/Faithful,RGBA/alpha,checker/dark/light,wipe,5stageaspects;HighScoresapproved + historyretained')
